        "T": {
            "description": "Normal on-track pass (fallback)",
            "rule": "Event does not match R, P, or S."
        }
    },
    "tables_used": {
        "lap_positions": "Race lap positions (filtered: lap_type='Race', lap>=1). Columns: race_id, driver_id, lap, position, lap_type.",
