        "retirements": "Retirement events for R classification. Columns: race_id, driver_id, lap.",
        "pit_stops": "Pit stop events for P classification. Columns: race_id, driver_id, lap.",
        "races_ext": "Race metadata including is_pit_data_available flag for Part A scope. Columns: race_id, is_pit_data_available.",
        "drivers": "Driver names (forename, surname) for Part C output."
    },
    "per_part_scope": {
        "partA": "All races where races_ext.is_pit_data_available = 1. Count all valid overtake events across all eligible race laps in those races.",
        "partB": "All races (no pit-data filter). Count only events with event lap between 1 and 5 inclusive.",
        "partC": "All races, all eligible race laps. Count only T-classified events. For each T event: overtaking_driver gets +1 overtook, overtaken_driver gets +1 was_overtaken. Output drivers where was_overtaken > overtook."
